"""Markdown → safe HTML for the preview pane.

Kept free of Qt so pytest can exercise it without a display.
"""

from __future__ import annotations

import re

from markdown_it import MarkdownIt
from mdit_py_plugins.gfm import gfm_plugin
from pygments import highlight
from pygments.formatters.html import HtmlFormatter
from pygments.lexers import get_lexer_by_name
from pygments.util import ClassNotFound

# Inline styles are understood by QTextBrowser; classes generated by the
# default formatter are not reliably applied by Qt's rich-text parser.
_CODE_FORMATTER = HtmlFormatter(
    style="github-dark",
    noclasses=True,
    nowrap=True,
)


def _highlight_code(code: str, language: str, _attrs: str) -> str:
    """Highlight code when the language is recognized.

    Args:
        code (str): Source code to highlight.
        language (str): Name of the lexer to use.
        _attrs (str): Additional attributes, unused by this function.

    Returns:
        str: Highlighted Pygments HTML for a recognized language, or an empty string if
            the language is missing or unknown.
    """
    if not language:
        return ""
    try:
        lexer = get_lexer_by_name(language)
    except ClassNotFound:
        return ""
    return highlight(code, lexer, _CODE_FORMATTER)


# GFM preset: tables, strikethrough, autolinks, task lists, footnotes.
# HTML enabled so <img>, <br>, <b>, etc. pass through; tagfilter blocks
# the dangerous tags per GFM spec §6.12.
# ponytail: single shared parser; rebuild if you ever need per-call options.
_PARSER = MarkdownIt(
    "commonmark",
    {
        "html": True,
        "linkify": False,
        "highlight": _highlight_code,
    },
).use(gfm_plugin)

# GFM "Disallowed Raw HTML" tagfilter (spec §6.12).
# Escapes the opening `<` of dangerous tags; all other HTML passes through.
_DISALLOWED_TAGS = re.compile(
    r"<(/?)(title|textarea|style|xmp|iframe|noembed|noframes|script|plaintext)\b",
    re.IGNORECASE,
)


def _tagfilter(html: str) -> str:
    """Escape disallowed raw HTML tags.

    Args:
        html (str): HTML text to filter.

    Returns:
        str: HTML with the opening angle bracket of each matched disallowed tag replaced
            by `&lt;`.
    """
    return _DISALLOWED_TAGS.sub(r"&lt;\1\2", html)


# Loose task syntax people type: ``- [] foo`` (GFM needs a space inside).
_LOOSE_EMPTY_BOX = re.compile(
    r"^(\s*(?:[-*+]|\d+[.)])\s+)\[\](\s+)",
    re.MULTILINE,
)

# QTextBrowser drops <input type="checkbox">. Inject real glyphs instead of
# relying on Qt's flaky li.checked / li.unchecked markers.
_CHECKED_ITEM = re.compile(
    r'<li class="task-list-item[^"]*">\s*'
    r'<input[^>]*\bchecked\b[^>]*type="checkbox"[^>]*>\s*',
    re.IGNORECASE,
)
_UNCHECKED_ITEM = re.compile(
    r'<li class="task-list-item[^"]*">\s*'
    r'<input[^>]*type="checkbox"[^>]*>\s*',
    re.IGNORECASE,
)

_CHECK_ON = "\u2611\u00a0"  # ☑ + nbsp
_CHECK_OFF = "\u2610\u00a0"  # ☐ + nbsp

# Permanent dark preview — matches the editor chrome.
_CSS = """
body {
  font-family: "Segoe UI", "Segoe UI Variable", sans-serif;
  font-size: 14px;
  line-height: 1.5;
  color: #e6e6e6;
  background: #1e1e1e;
  margin: 12px 16px;
}
pre, code {
  font-family: Consolas, "Cascadia Mono", monospace;
  font-size: 13px;
  background: #2d2d2d;
  color: #f0a0a0;
}
pre {
  padding: 10px 12px;
  overflow-x: auto;
  border-radius: 4px;
  line-height: normal;
}
code { padding: 1px 4px; border-radius: 3px; }
pre code { padding: 0; background: transparent; }
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.25;
  color: #79b8ff;
}
a { color: #58a6ff; }
blockquote {
  margin-left: 0;
  padding-left: 12px;
  border-left: 3px solid #484848;
  color: #9a9a9a;
}
table { border-collapse: collapse; margin: 0.5em 0; }
th, td { border: 1px solid #484848; padding: 6px 10px; }
th { background: #2d2d2d; font-weight: 600; }
tr:nth-child(even) td { background: #252526; }
hr { border: none; border-top: 1px solid #484848; }
img { max-width: 100%; height: auto; }
/* Hide the default bullet; the ☑/☐ glyph is the marker. */
ul.contains-task-list { list-style: none; padding-left: 0.35em; }
ul.contains-task-list > li { margin: 0.15em 0; }
"""


def _normalize_task_markdown(source: str) -> str:
    """Normalize recognized empty task boxes in Markdown.

    Args:
        source (str): Markdown text to normalize.

    Returns:
        str: The source with matching empty task boxes replaced by ``[ ]``.
    """
    return _LOOSE_EMPTY_BOX.sub(r"\1[ ]\2", source)


def _qtify_tasklists(html: str) -> str:
    """Replace task-list checkbox inputs with Unicode ballot boxes.

    Args:
        html (str): HTML containing task-list checkbox inputs.

    Returns:
        str: HTML with recognized checked and unchecked checkbox inputs replaced by list
            items containing Unicode ballot boxes. Checked inputs are replaced first.
    """
    # Checked first so the second pattern does not steal them.
    html = _CHECKED_ITEM.sub(f"<li>{_CHECK_ON}", html)
    return _UNCHECKED_ITEM.sub(f"<li>{_CHECK_OFF}", html)


def to_html(source: str) -> str:
    """Render Markdown source as a complete HTML document.

    Args:
        source (str): Markdown text to render.

    Returns:
        str: HTML document containing a UTF-8 character-set declaration, embedded CSS,
            and the rendered body.
    """
    rendered = _PARSER.render(_normalize_task_markdown(source))
    body = _qtify_tasklists(_tagfilter(rendered))
    return (
        "<!DOCTYPE html><html><head><meta charset='utf-8'>"
        f"<style>{_CSS}</style></head><body>{body}</body></html>"
    )
